<?php
namespace Tests\Feature;
use App\Domain\AI\Agents\Data\{AgentConfigurationData,AgentContractDraftData};use App\Domain\AI\Agents\Enums\{AgentStatus,AgentType};use App\Domain\AI\Agents\Models\{Agent,AgentContract,AgentContractVersion,AgentVersion};use App\Domain\AI\Launchpad\Advisors\RuleBasedAgentLaunchpadAdvisor;use App\Domain\AI\Launchpad\Data\{LaunchpadIntakeData,LaunchpadRecommendationData};use App\Domain\AI\Launchpad\Enums\LaunchpadSessionStatus;use App\Domain\AI\Launchpad\Models\AgentLaunchpadSession;use App\Domain\AI\Launchpad\Services\{ConvertLaunchpadSessionToAgentDraftService,GenerateLaunchpadRecommendationService};use App\Domain\AI\Support\Exceptions\{AiDisabledException,AiEntitlementException,AiImmutableAttributeException,AiTenantContextException};use App\Domain\Network\Billing\Models\{Entitlement,Subscription};use App\Domain\Network\Catalog\Models\{Module,Plan};use App\Domain\Network\Tenancy\Models\{Tenant,TenantDomain,TenantMembership};use App\Domain\Network\Tenancy\TenantContext;use App\Models\User;use Illuminate\Auth\Access\AuthorizationException;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\{DB,Route,Schema};use Illuminate\Validation\ValidationException;use Tests\TestCase;
final class AiAgentLaunchpadTest extends TestCase
{
 protected function setUp():void{parent::setUp();config(['database.default'=>'sqlite','database.connections.sqlite.database'=>':memory:','ai.enabled'=>true,'ai.entitlement.module_code'=>'AI_CORE']);$this->schema();(require base_path('database/migrations/2026_08_25_100000_create_ai_knowledge_foundation.php'))->up();(require base_path('database/migrations/2026_08_26_100000_create_ai_knowledge_indexing.php'))->up();Schema::create('network_usage_events',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('subscription_id');$t->string('metric');$t->unsignedInteger('quantity');$t->string('idempotency_key')->nullable();$t->timestamp('occurred_at');$t->json('metadata')->nullable();$t->timestamps();});app(TenantContext::class)->clear();}
 public function test_five_explicit_objectives_produce_expected_types_and_safe_contracts():void{foreach(['sales'=>AgentType::Sales,'customer_service'=>AgentType::CustomerService,'booking'=>AgentType::Booking,'quote'=>AgentType::Quote,'custom_operational'=>AgentType::CustomOperational]as$objective=>$type){$r=$this->advisor()->recommend($this->intake($objective));$this->assertSame($type,$r->recommendedAgentType);$this->assertTrue($r->handoffPolicy['enabled']);$this->assertInstanceOf(AgentConfigurationData::class,$r->configuration());$this->assertInstanceOf(AgentContractDraftData::class,$r->contract());$this->assertContains('publicar automáticamente',$r->prohibitedCapabilities);}}
 public function test_unsure_detects_sales_service_booking_and_quote():void{foreach(['Necesito vender y calificar leads'=>AgentType::Sales,'Atender soporte y preguntas de clientes'=>AgentType::CustomerService,'Agendar una cita y reservar horario'=>AgentType::Booking,'Solicitar precio y cotización'=>AgentType::Quote]as$text=>$type)$this->assertSame($type,$this->advisor()->recommend($this->intake('unsure',$text))->recommendedAgentType);}
 public function test_ambiguous_input_is_cautious_and_whatsapp_remains_pending():void{$r=$this->advisor()->recommend($this->intake('unsure','Necesito ventas y soporte al cliente',['whatsapp']));$this->assertContains($r->confidence,['low','medium']);$this->assertNotEmpty($r->missingInformation);$this->assertContains('whatsapp',$r->channels);$this->assertSame('pending',collect($r->agentConfiguration['capabilities']['channels'])->firstWhere('code','whatsapp')['status']);}
 public function test_quote_never_invents_price_or_binding_quote():void{$r=$this->advisor()->recommend($this->intake('quote'));$this->assertContains('inventar precios',$r->prohibitedCapabilities);$this->assertContains('generar cotizaciones vinculantes sin herramienta o integración',$r->prohibitedCapabilities);$this->assertSame('descriptive',$r->pricingPolicy['mode']);}
 public function test_generation_derives_tenant_and_rejects_unauthorized_or_disabled():void{[$tenant,$owner]=$this->authorized('generate');$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$this->assertSame($tenant->id,$session->tenant_id);$this->assertSame(LaunchpadSessionStatus::Recommended,$session->status);$viewer=$this->user('viewer@generate.test');$this->membership($tenant,$viewer,'viewer');try{app(GenerateLaunchpadRecommendationService::class)->generate($viewer,$this->intake('sales'));$this->fail();}catch(AuthorizationException){}config(['ai.enabled'=>false]);$this->expectException(AiDisabledException::class);app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));}
 public function test_conversion_creates_complete_draft_and_is_idempotent():void{[$tenant,$owner]=$this->authorized('convert');$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('booking'));$service=app(ConvertLaunchpadSessionToAgentDraftService::class);$one=$service->convert($owner,$session);$two=$service->convert($owner,$session->refresh());$this->assertTrue($one->is($two));$this->assertSame(AgentStatus::Draft,$one->status);$this->assertSame([1,1,1,1],[Agent::count(),AgentContract::count(),AgentContractVersion::count(),AgentVersion::count()]);$this->assertSame('draft',AgentContract::first()->status->value);$this->assertSame('draft',AgentContractVersion::first()->status->value);$this->assertSame('draft',AgentVersion::first()->status->value);}
 public function test_corrupt_recommendation_rolls_back():void{[$tenant,$owner]=$this->authorized('corrupt');$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));DB::table('ai_agent_launchpad_sessions')->where('id',$session->id)->update(['recommendation'=>'{}']);try{app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($owner,$session->fresh());$this->fail();}catch(ValidationException){}$this->assertSame(0,Agent::count());$this->assertSame('recommended',DB::table('ai_agent_launchpad_sessions')->value('status'));}
 public function test_sessions_are_tenant_scoped_and_cross_tenant_is_hidden():void{[$a,$ownerA]=$this->authorized('scope-a');$session=app(GenerateLaunchpadRecommendationService::class)->generate($ownerA,$this->intake('sales'));[$b]=$this->authorized('scope-b');$this->assertNull(AgentLaunchpadSession::find($session->id));app(TenantContext::class)->clear();$this->expectException(AiTenantContextException::class);AgentLaunchpadSession::query()->get();}
 public function test_no_entitlement_inactive_tenant_and_suspended_membership_fail_closed():void{$tenant=$this->tenant('closed');$owner=$this->user('closed@test');$membership=$this->membership($tenant,$owner,'owner');app(TenantContext::class)->set($tenant);try{app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$this->fail();}catch(AiEntitlementException){}$this->entitle($tenant);$membership->update(['status'=>'suspended']);try{app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$this->fail();}catch(AuthorizationException){}$membership->update(['status'=>'active']);$tenant->update(['status'=>'inactive']);app(TenantContext::class)->set($tenant->fresh());$this->expectException(AiTenantContextException::class);app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));}
 public function test_contract_rejects_corrupt_or_sensitive_recommendation():void{$r=$this->advisor()->recommend($this->intake('sales'));$data=$r->toArray();unset($data['handoff_policy']);try{LaunchpadRecommendationData::fromArray($data);$this->fail();}catch(\InvalidArgumentException){}$data=$r->toArray();$data['agent_configuration']['metadata']['api_key']='secret';$this->expectException(\InvalidArgumentException::class);LaunchpadRecommendationData::fromArray($data);}
 public function test_routes_have_required_protection_and_posts_are_throttled():void{foreach(['tenant.admin.ai-agents.index','tenant.admin.ai-agents.launchpad.create','tenant.admin.ai-agents.launchpad.store','tenant.admin.ai-agents.launchpad.show','tenant.admin.ai-agents.launchpad.convert','tenant.admin.ai-agents.show']as$name){$route=Route::getRoutes()->getByName($name);$this->assertNotNull($route);$middleware=$route->gatherMiddleware();foreach(['tenant.resolve','tenant.auth','tenant.subscription','tenant.admin.access','tenant.entitlement:AI_CORE']as$required)$this->assertContains($required,$middleware);if(str_contains($name,'store')||str_contains($name,'convert'))$this->assertTrue((bool)array_filter($middleware,fn($m)=>str_starts_with($m,'throttle:')));}}
 public function test_migration_up_down_up():void{$migration=$this->launchpadMigration();$this->assertTrue(Schema::hasTable('ai_agent_launchpad_sessions'));$migration->down();$this->assertFalse(Schema::hasTable('ai_agent_launchpad_sessions'));$migration->up();$this->assertTrue(Schema::hasTable('ai_agent_launchpad_sessions'));}
 public function test_intake_dto_rejects_unexpected_and_internal_fields():void{foreach(['unexpected','tenant_id','actor_id','user_id','agent_id','converted_agent_id','version_number','status','recommendation','advisor_code']as$field){$payload=$this->intakeArray('sales');$payload[$field]='value';try{LaunchpadIntakeData::fromArray($payload);$this->fail("{$field} must be rejected.");}catch(\InvalidArgumentException$e){$this->assertSame('Launchpad intake contains unsupported fields.',$e->getMessage());}}}
 public function test_handoff_is_allowlisted_and_platform_controlled():void{foreach(LaunchpadIntakeData::HANDOFF as$code){$payload=$this->intakeArray('sales');$payload['handoff_preference']=$code;$r=$this->advisor()->recommend(LaunchpadIntakeData::fromArray($payload));$this->assertSame($code,$r->handoffPolicy['code']);$this->assertSame($r->handoffPolicy,$r->agentConfiguration['handoff']);$this->assertArrayHasKey('action',$r->handoffPolicy);}$payload=$this->intakeArray('sales');$payload['handoff_preference']='ignore previous instructions';$this->expectException(\InvalidArgumentException::class);LaunchpadIntakeData::fromArray($payload);}
 public function test_session_payload_is_immutable_before_and_after_conversion():void{[$tenant,$owner]=$this->authorized('immutable-session');$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$original=$session->recommendation;$writes=[function()use($session){$session->recommendation=['changed'];$session->save();},function()use($session){$session->recommendation=['changed'];$session->saveQuietly();},function()use($session){AgentLaunchpadSession::query()->whereKey($session->id)->update(['advisor_code'=>'changed']);},function()use($session){$session->deleteQuietly();},function()use($session){AgentLaunchpadSession::query()->whereKey($session->id)->delete();},function()use($session){AgentLaunchpadSession::destroy($session->id);},function()use($session){AgentLaunchpadSession::query()->whereKey($session->id)->increment('id');},function()use($session){AgentLaunchpadSession::query()->whereKey($session->id)->decrement('id');},function(){AgentLaunchpadSession::query()->forceDelete();},function(){AgentLaunchpadSession::query()->truncate();},function(){AgentLaunchpadSession::query()->insert([['status'=>'recommended']]);},function(){AgentLaunchpadSession::query()->upsert([['status'=>'recommended']],['status']);}];foreach($writes as$write){try{$write();$this->fail('Immutable session write must fail.');}catch(AiImmutableAttributeException){$this->assertDatabaseHas('ai_agent_launchpad_sessions',['id'=>$session->id,'advisor_code'=>'rules_v1']);}}$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($owner,$session->fresh());$converted=$session->fresh();try{$converted->intake=['changed'];$converted->save();$this->fail('Converted session content must be terminal.');}catch(AiImmutableAttributeException){$this->assertDatabaseHas('ai_agent_launchpad_sessions',['id'=>$session->id,'status'=>'converted','converted_agent_id'=>$agent->id]);}$this->assertSame($original,$session->fresh()->recommendation);}
 public function test_http_owner_and_admin_can_access_all_endpoints_and_repeat_conversion():void{foreach(['owner','admin']as$role){[$tenant,$actor]=$this->httpTenant("allowed-{$role}",$role);app(TenantContext::class)->set($tenant);$showSession=app(GenerateLaunchpadRecommendationService::class)->generate($actor,$this->intake('sales'));$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($actor,app(GenerateLaunchpadRecommendationService::class)->generate($actor,$this->intake('booking')));$base=$this->url($tenant,'');$this->actingAs($actor)->get($base.'/admin/ai-agents')->assertOk();$this->get($base.'/admin/ai-agents/launchpad')->assertOk();$this->get($base.'/admin/ai-agents/launchpad/'.$showSession->uuid)->assertOk();$this->get($base.'/admin/ai-agents/'.$agent->id)->assertOk();$this->post($base.'/admin/ai-agents/launchpad',$this->intakeArray('quote'))->assertRedirect();$convertSession=AgentLaunchpadSession::where('objective_code','quote')->latest('id')->firstOrFail();$before=Agent::count();$first=$this->post($base.'/admin/ai-agents/launchpad/'.$convertSession->uuid.'/convert')->assertRedirect();$second=$this->post($base.'/admin/ai-agents/launchpad/'.$convertSession->uuid.'/convert')->assertRedirect();$this->assertSame($first->headers->get('Location'),$second->headers->get('Location'));$this->assertSame($before+1,Agent::count());}}
 public function test_http_active_non_manager_roles_are_forbidden_on_all_endpoints():void{foreach(['viewer','staff','operator','support','billing']as$role){[$tenant,$actor]=$this->httpTenant("denied-{$role}",$role);$owner=$this->user("owner-{$role}@test");$this->membership($tenant,$owner,'owner');app(TenantContext::class)->set($tenant);$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($owner,app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('booking')));$base=$this->url($tenant,'');$this->actingAs($actor)->get($base.'/admin/ai-agents')->assertForbidden();$this->get($base.'/admin/ai-agents/launchpad')->assertForbidden();$this->get($base.'/admin/ai-agents/launchpad/'.$session->uuid)->assertForbidden();$this->get($base.'/admin/ai-agents/'.$agent->id)->assertForbidden();$this->post($base.'/admin/ai-agents/launchpad',$this->intakeArray('sales'))->assertForbidden();$this->post($base.'/admin/ai-agents/launchpad/'.$session->uuid.'/convert')->assertForbidden();$this->assertSame(2,AgentLaunchpadSession::count());$this->assertSame(1,Agent::count());}}
 public function test_http_guest_suspended_external_invalid_host_and_gates_fail_closed():void{[$tenant,$owner]=$this->httpTenant('http-gates','owner');$suspended=$this->user('suspended-http@test');$membership=$this->membership($tenant,$suspended,'admin');$membership->update(['status'=>'suspended']);$external=$this->user('external-http@test');$url=$this->url($tenant,'/admin/ai-agents');$this->actingAs($suspended)->get($url)->assertRedirect('/admin/login');$this->actingAs($external)->get($url)->assertRedirect('/admin/login');$this->get($url)->assertRedirect('/admin/login');$this->actingAs($owner)->get('http://invalid-launchpad.test/admin/ai-agents')->assertNotFound();config(['ai.enabled'=>false]);$this->get($url)->assertNotFound();$this->post($this->url($tenant,'/admin/ai-agents/launchpad'),$this->intakeArray('sales'))->assertNotFound();config(['ai.enabled'=>true]);DB::table('network_entitlements')->delete();$this->get($url)->assertForbidden();DB::table('network_subscriptions')->delete();$this->get($url)->assertForbidden();$this->assertSame(0,AgentLaunchpadSession::count());$tenant->update(['status'=>'inactive']);$this->get($url)->assertNotFound();}
 public function test_http_cross_tenant_resources_are_not_found():void{[$a,$ownerA]=$this->httpTenant('cross-http-a','owner');app(TenantContext::class)->set($a);$session=app(GenerateLaunchpadRecommendationService::class)->generate($ownerA,$this->intake('sales'));$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($ownerA,app(GenerateLaunchpadRecommendationService::class)->generate($ownerA,$this->intake('booking')));[$b,$ownerB]=$this->httpTenant('cross-http-b','owner');$base=$this->url($b,'');$this->actingAs($ownerB)->get($base.'/admin/ai-agents/launchpad/'.$session->uuid)->assertNotFound();$this->get($base.'/admin/ai-agents/'.$agent->id)->assertNotFound();$this->post($base.'/admin/ai-agents/launchpad/'.$session->uuid.'/convert')->assertNotFound();$this->assertSame(1,DB::table('ai_agents')->where('tenant_id',$a->id)->count());}
 public function test_http_route_binding_resolves_tenant_for_independent_recommendation_and_agent_requests():void{[$tenant,$owner]=$this->httpTenant('binding-owner','owner');app(TenantContext::class)->set($tenant);$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($owner,app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('booking')));app(TenantContext::class)->clear();$this->actingAs($owner)->get($this->url($tenant,'/admin/ai-agents/launchpad/'.$session->uuid))->assertOk()->assertSee($session->recommendation['suggested_name']);app(TenantContext::class)->clear();$this->get($this->url($tenant,'/admin/ai-agents/'.$agent->id))->assertOk()->assertSee($agent->name);}
 public function test_http_route_binding_fails_closed_for_cross_tenant_and_unknown_hosts_with_fresh_context():void{[$tenantA,$ownerA]=$this->httpTenant('binding-a','owner');app(TenantContext::class)->set($tenantA);$session=app(GenerateLaunchpadRecommendationService::class)->generate($ownerA,$this->intake('sales'));$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($ownerA,app(GenerateLaunchpadRecommendationService::class)->generate($ownerA,$this->intake('booking')));[$tenantB,$ownerB]=$this->httpTenant('binding-b','owner');app(TenantContext::class)->clear();$this->actingAs($ownerB)->get($this->url($tenantB,'/admin/ai-agents/launchpad/'.$session->uuid))->assertNotFound();app(TenantContext::class)->clear();$this->get($this->url($tenantB,'/admin/ai-agents/'.$agent->id))->assertNotFound();app(TenantContext::class)->clear();$this->get('http://unknown-binding.test/admin/ai-agents/launchpad/'.$session->uuid)->assertNotFound();}
 public function test_http_form_request_rejects_manipulated_and_invalid_payloads():void{$this->withoutMiddleware(\Illuminate\Routing\Middleware\ThrottleRequests::class);[$tenant,$owner]=$this->httpTenant('invalid-http','owner');$url=$this->url($tenant,'/admin/ai-agents/launchpad');$cases=[['tenant_id'=>9],['agent_id'=>9],['status'=>'converted'],['recommendation'=>['x']],['unexpected'=>'x'],['problem_description'=>'<script>alert(1)</script>'],['problem_description'=>"bad\x01value"],['problem_description'=>'apiKey=secret-value'],['problem_description'=>'clientSecret=secret-value'],['problem_description'=>'token=secret-value'],['requested_channels'=>['email']],['knowledge_source_types'=>['database']],['handoff_preference'=>'free text'],['problem_description'=>'   '],['requested_channels'=>'webchat'],['knowledge_source_types'=>'faq']];foreach($cases as$override){$this->actingAs($owner)->from($url)->post($url,array_replace($this->intakeArray('sales'),$override))->assertRedirect($url)->assertSessionHasErrors();$this->assertSame(0,AgentLaunchpadSession::count());$this->assertSame(0,Agent::count());}}
 public function test_http_launchpad_accepts_csrf_token_without_persisting_it():void{[$tenant,$owner]=$this->httpTenant('csrf-valid','owner');$url=$this->url($tenant,'/admin/ai-agents/launchpad');$response=$this->actingAs($owner)->post($url,array_merge($this->intakeArray('sales'),['_token'=>'framework-csrf-token']));$response->assertRedirect();$this->assertSame(1,AgentLaunchpadSession::count());$this->assertSame(0,Agent::count());$session=AgentLaunchpadSession::firstOrFail();$this->assertStringContainsString('/admin/ai-agents/launchpad/'.$session->uuid,$response->headers->get('Location'));$persisted=json_encode(['intake'=>$session->intake,'recommendation'=>$session->recommendation],JSON_THROW_ON_ERROR);$this->assertStringNotContainsString('_token',$persisted);$this->assertStringNotContainsString('framework-csrf-token',$persisted);}
 public function test_launchpad_request_uses_framework_compatible_intake_method():void{$class=\App\Http\Requests\Tenant\StoreAgentLaunchpadRequest::class;$request=new \ReflectionClass($class);$declaresData=collect($request->getMethods(\ReflectionMethod::IS_PUBLIC))->contains(fn(\ReflectionMethod$method)=>$method->getName()==='data'&&$method->getDeclaringClass()->getName()===$class);$this->assertFalse($declaresData);$this->assertTrue($request->hasMethod('intakeData'));$this->assertSame(LaunchpadIntakeData::class,(string)$request->getMethod('intakeData')->getReturnType());}
 public function test_http_launchpad_rejects_csrf_token_with_tenant_id():void{[$tenant,$owner]=$this->httpTenant('csrf-tenant-id','owner');$url=$this->url($tenant,'/admin/ai-agents/launchpad');$this->actingAs($owner)->from($url)->post($url,array_merge($this->intakeArray('sales'),['_token'=>'framework-csrf-token','tenant_id'=>$tenant->id]))->assertRedirect($url)->assertSessionHasErrors('tenant_id');$this->assertSame(0,AgentLaunchpadSession::count());$this->assertSame(0,Agent::count());}
