 public function test_http_escapes_agent_name_in_title_and_body():void{[$tenant,$owner]=$this->httpTenant('xss-http','owner');app(TenantContext::class)->set($tenant);$agent=new Agent();$agent->code='XSS-AGENT';$agent->name='<script>alert(1)</script>';$agent->description='<img src=x onerror=alert(1)>';$agent->type=AgentType::Sales;$agent->status=AgentStatus::Draft;$agent->created_by_user_id=$owner->id;$agent->save();$response=$this->actingAs($owner)->get($this->url($tenant,'/admin/ai-agents/'.$agent->id))->assertOk();$response->assertSee('&lt;script&gt;alert(1)&lt;/script&gt;',false)->assertDontSee('<script>alert(1)</script>',false)->assertDontSee('<img src=x onerror=alert(1)>',false);}
 public function test_http_navigation_and_dashboard_visibility_follow_role_and_entitlement():void{foreach(['owner','admin']as$role){[$tenant,$actor]=$this->httpTenant("nav-{$role}",$role);$response=$this->actingAs($actor)->get($this->url($tenant,'/admin'))->assertOk();$response->assertSee('Mis agentes')->assertSee('/admin/ai-agents/launchpad',false);}[$viewerTenant,$viewer]=$this->httpTenant('nav-viewer','viewer');$this->actingAs($viewer)->get($this->url($viewerTenant,'/admin'))->assertOk()->assertDontSee('Mis agentes');[$plain,$plainOwner]=$this->httpTenant('nav-plain','owner');$subscription=Subscription::where('tenant_id',$plain->id)->firstOrFail();$shipping=Module::firstOrCreate(['code'=>'SHIPPING'],['name'=>'Shipping','type'=>'core','is_active'=>true,'sort_order'=>2]);Entitlement::create(['subscription_id'=>$subscription->id,'tenant_id'=>$plain->id,'module_id'=>$shipping->id,'code'=>'SHIPPING','is_enabled'=>true,'source'=>'plan']);DB::table('network_entitlements')->where('tenant_id',$plain->id)->where('code','AI_CORE')->delete();$this->actingAs($plainOwner)->get($this->url($plain,'/admin'))->assertOk()->assertDontSee('Mis agentes');}
 public function test_migration_has_real_foreign_keys_indexes_restrict_and_tenant_agent_guard():void{$foreign=collect(DB::select("PRAGMA foreign_key_list('ai_agent_launchpad_sessions')"));$this->assertSame(5,$foreign->count());$this->assertSame(2,$foreign->where('table','ai_agents')->count());$this->assertSame(['RESTRICT'],array_values(array_unique($foreign->pluck('on_delete')->all())));$indexes=collect(DB::select("PRAGMA index_list('ai_agent_launchpad_sessions')"))->pluck('name');foreach(['ai_launchpad_tenant_status_ix','ai_launchpad_objective_ix','ai_launchpad_converted_agent_ix','ai_launchpad_tenant_id_uq','ai_agent_launchpad_sessions_uuid_unique']as$name)$this->assertContains($name,$indexes);[$a,$ownerA]=$this->authorized('fk-a');$session=app(GenerateLaunchpadRecommendationService::class)->generate($ownerA,$this->intake('sales'));[$b,$ownerB]=$this->authorized('fk-b');$agent=app(\App\Domain\AI\Agents\Services\CreateAgentDraftService::class)->create($ownerB,new \App\Domain\AI\Agents\Data\CreateAgentDraftData('FK-B','Agent B',null,AgentType::Sales,$this->advisor()->recommend($this->intake('sales'))->contract(),$this->advisor()->recommend($this->intake('sales'))->configuration()))->agent;try{DB::table('ai_agent_launchpad_sessions')->where('id',$session->id)->update(['converted_agent_id'=>$agent->id]);$this->fail('Cross-tenant converted Agent must fail.');}catch(\Illuminate\Database\QueryException){$this->assertNull(DB::table('ai_agent_launchpad_sessions')->where('id',$session->id)->value('converted_agent_id'));}}
 public function test_migration_restricts_deleting_referenced_tenant_user_and_agent():void{[$tenant,$owner]=$this->authorized('restrict-launchpad');$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$agent=app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($owner,$session);foreach([fn()=>DB::table('network_tenants')->where('id',$tenant->id)->delete(),fn()=>DB::table('users')->where('id',$owner->id)->delete(),fn()=>DB::table('ai_agents')->where('id',$agent->id)->delete()]as$delete){try{$delete();$this->fail('Referenced delete must be restricted.');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseHas('ai_agent_launchpad_sessions',['id'=>$session->id,'converted_agent_id'=>$agent->id]);}}}
 public function test_mark_converted_failure_rolls_back_complete_aggregate():void{[$tenant,$owner]=$this->authorized('mark-rollback');$session=app(GenerateLaunchpadRecommendationService::class)->generate($owner,$this->intake('sales'));$fail=true;AgentLaunchpadSession::saving(function(AgentLaunchpadSession$model)use(&$fail){if($fail&&$model->status===LaunchpadSessionStatus::Converted)throw new \RuntimeException('mark failure');});try{app(ConvertLaunchpadSessionToAgentDraftService::class)->convert($owner,$session);$this->fail('markConverted failure expected.');}catch(\RuntimeException$e){$this->assertSame('mark failure',$e->getMessage());}$fail=false;$this->assertSame([0,0,0,0],[Agent::count(),AgentContract::count(),AgentContractVersion::count(),AgentVersion::count()]);$this->assertSame(LaunchpadSessionStatus::Recommended,$session->fresh()->status);}
